import type { ResolvedTheme } from '#lib/theme.ts';

/**
 * The rendered tally ornament, one file per palette (docs/decisions.md §306).
 *
 * Both are generated by `assets/marketing/gen-marketing.sh` from the same
 * Blender scene with two lightings: the dark one was composed for navy (a cool
 * fill that keeps the shadow side off black), the light one for a pale ground
 * (deeper gold, so the highlights do not dissolve into the page). Same
 * geometry, camera and trim, so both are 1100 × 460 and swapping one for the
 * other never moves the layout — the generator refuses to write a pair that
 * disagrees, and `ornament.test.ts` checks the committed files.
 *
 * Chosen from `theme.resolved` rather than a `<picture>` media query: a
 * `prefers-color-scheme` source follows the OS, not the visitor's stored
 * Light / Dark choice.
 *
 * Paths are `asset()`-relative (no leading slash), kept as literals so
 * `asset()`'s typed path union still checks that each file exists.
 */
export const TALLY_ORNAMENT = {
	dark: 'marketing/tally-split.webp',
	light: 'marketing/tally-split-light.webp'
} as const satisfies Record<ResolvedTheme, string>;

/** The intrinsic size every variant shares — the `<img>`'s width/height. */
export const TALLY_ORNAMENT_SIZE = { width: 1100, height: 460 } as const;
